import Ajax from"core/ajax";export const init=cmid=>{const dashboard=document.querySelector("[data-checkpoint-dashboard]");if(!dashboard){return}const refresh=async()=>{const[data]=await Ajax.call([{methodname:"mod_checkpoint_get_status",args:{cmid:cmid}}]);for(const key of["submitted","graded","reopened","late"]){const target=dashboard.querySelector(`[data-checkpoint-${key}]`);if(target){target.textContent=data[key]}}};refresh().catch(()=>{})};